mapper.select:
SELECT  FROM 
WHERE 

    AND LOWER(c.name) LIKE CONCAT('%',LOWER(#{filter.name}),'%') ESCAPE '!'

AND c.source_id=#{filter.sourceId}
AND s.adapter_type=#{filter.adapterType}
AND c.lifecycle=#{filter.lifecycle}



            AND c.group_id IN
            #{group}

        AND 1=0


ORDER BY c.created_at DESC,c.id DESC

SELECT representative.* FROM (
    SELECT c.*,ROW_NUMBER() OVER (
        PARTITION BY  ORDER BY c.id
    ) AS representative_order
    FROM camera_channel c JOIN camera_source s ON s.id=c.source_id
    LEFT JOIN camera_device d ON d.id=c.device_id AND d.source_id=c.source_id
    WHERE ()
    AND c.lifecycle='ENABLED' AND c.group_id IN
    #{groupId}
) representative WHERE representative.representative_order=1 ORDER BY representative.id LIMIT #{limit}

SELECT representative.* FROM (
    SELECT c.*,ROW_NUMBER() OVER (
        PARTITION BY  ORDER BY c.id
    ) AS representative_order
    FROM camera_channel c JOIN camera_source s ON s.id=c.source_id
    LEFT JOIN camera_device d ON d.id=c.device_id AND d.source_id=c.source_id
    WHERE ()
    AND c.lifecycle='ENABLED'

        AND  IN
        #{key}

) representative
WHERE representative.representative_order=1
ORDER BY representative.id LIMIT #{limit}
